void real(const std::string& input,const fs::path& output){
    check(has_expression_reduction(),"Real route requires admitted native algebra backend");fs::create_directory(output);const auto project=Project::open(input);const auto image=project->active_image();const auto matrix_ids=expression_matrix_ids(*project,image);check(matrix_ids.size()==1,"Real route needs one explicit raw matrix");const auto source=reopen_expression_matrix(*project,image,matrix_ids[0]);check(source->metadata().features==32285 && source->metadata().observations==2702,"Real reduction source is not the retained full matrix");const auto normalizations=expression_normalization_ids(*project,image,matrix_ids[0]);check(!normalizations.empty(),"Reuse an admitted A01 normalization record instead of deriving a projected library");J features=J::array();for(const auto& f:source->feature_page(0,512))features.push_back(f.id);J spec={{"schema","qpx.expression-reduction-spec/1"},{"method","centered-pca"},{"features",features},{"normalization",normalizations[0]},{"components",4},{"clusters",4},{"seed",123},{"max_iterations",200}};write(output/"spec.json",spec.dump(2));ExpressionReductionWorkflowOptions options;options.image=image;options.matrix_id=matrix_ids[0];options.spec_path=(output/"spec.json").u8string();const auto result=run_expression_reduction(input,(output/"saved.qpx").u8string(),options);check(result->features().size()==512 && result->observation_ids().size()==2702 && result->value_domain()=="log1p-library-size-normalized","Real reduction domain/feature/observation identity differs");const auto k=result->options().components;for(std::size_t a=0;a<k;++a)for(std::size_t b=0;b<k;++b){double dot=0;for(std::size_t f=0;f<512;++f)dot+=result->loadings()[f*k+a]*result->loadings()[f*k+b];close(dot,a==b?1.:0.);}save_expression_embedding_csv(*result,(output/"embedding.csv").u8string());save_expression_loadings_csv(*result,(output/"loadings.csv").u8string());save_expression_reduction_svg(*result,(output/"scatter.svg").u8string());options.matrix_id.clear();options.spec_path.clear();options.record_id=result->id();options.work_bytes=64u*1024*1024;const auto replay=open_project_expression_reduction((output/"saved.qpx").u8string(),options,true);check(replay->id()==result->id() && replay->embedding()==result->embedding() && replay->labels()==result->labels(),"Real stored arrays/replay identity differs");write(output/"real.json",J{{"source_features",32285},{"selected_features",512},{"observations",2702},{"components",4},{"clusters",4},{"record",result->id()},{"source",result->source_sha256()},{"value_source",result->value_source_sha256()},{"seed",123},{"converged",result->converged()},{"iterations",result->iterations()},{"batches",result->batches()},{"peak_work_bytes",result->peak_work_bytes()},{"operations",result->operations()},{"distance_tests",result->distance_tests()},{"scope","Engineering reduction over an explicit512-gene selection; no biological labels/DE or whole-transcriptome selection claim"}}.dump(2));std::cout<<"Real native PCA/clustering:512 selected of32285 source features;2702 observations; exact archive/labels/seeded replay and native scatter export pass\n";
}
